var FAIR_BIDS_AFTER_PATRONAGE = 3

/** Technocratic fair bidding: all patronage routes (not outside corps), then 3 more fair bids. */
function syncContractFairChainComplete() {
    var patronageComplete = true
    for (var i = 0; i < CONTRACT_PATRONAGE_FLAGS.length; i++) {
        if ((Number(Q[CONTRACT_PATRONAGE_FLAGS[i]]) || 0) < 1) {
            patronageComplete = false
            break
        }
    }
    Q.contract_patronage_complete = patronageComplete ? 1 : 0
    if (patronageComplete && (Q.fair_contract_uses_at_patronage == null || isNaN(Number(Q.fair_contract_uses_at_patronage)))) {
        Q.fair_contract_uses_at_patronage = Number(Q.fair_contract_uses) || 0
    }
    var fairAfterPatronage = (Number(Q.fair_contract_uses) || 0) - (Number(Q.fair_contract_uses_at_patronage) || 0)
    Q.contract_fair_chain_complete = (patronageComplete && fairAfterPatronage >= FAIR_BIDS_AFTER_PATRONAGE) ? 1 : 0
    return Q.contract_fair_chain_complete
}

/** Grant 2 contracting draws per phase; unused visits bank for later phases. */
function syncContractingAllowance() {
    var phase = Number(Q.phase)
    if (isNaN(phase) || phase < 1) { phase = 1 }
    var through = Number(Q.contracting_allowance_through_phase)
    if (isNaN(through) || through < 0) { through = 0 }
    if (phase > through) {
        var grant = (phase - through) * CONTRACTING_VISITS_PER_PHASE
        Q.contracting_visits_remaining = (Number(Q.contracting_visits_remaining) || 0) + grant
        Q.contracting_allowance_through_phase = phase
    }
    if (Q.contracting_visits_remaining == null || isNaN(Number(Q.contracting_visits_remaining))) {
        Q.contracting_visits_remaining = 0
    }
    return Number(Q.contracting_visits_remaining) || 0
}

