function cableNegEffectiveRelief(downs, grossUp) {
    var i, grossDown = 0, out = []
    downs = downs || []
    if (grossUp < 2) { return out }
    for (i = 0; i < downs.length; i++) {
        if (downs[i].n > 0) { out.push({ corp: downs[i].corp, n: downs[i].n }) }
    }
    for (i = 0; i < out.length; i++) { grossDown += out[i].n }
    if (grossDown >= grossUp) {
        var budget = grossUp - 1
        for (i = 0; i < out.length; i++) {
            if (budget <= 0) { out[i].n = 0 }
            else if (out[i].n > budget) { out[i].n = budget; budget = 0 }
            else { budget -= out[i].n }
        }
    }
    return out
}
function cableNegApplyWithRivalRelief(ups, downs) {
    var i, grossUp = 0
    ups = ups || []
    for (i = 0; i < ups.length; i++) { grossUp += ups[i].n }
    downs = cableNegEffectiveRelief(downs, grossUp)
    for (i = 0; i < ups.length; i++) { cableNegReprisalAdd(ups[i].corp, ups[i].n) }
    for (i = 0; i < downs.length; i++) {
        if (downs[i].n > 0) { cableNegReprisalSub(downs[i].corp, downs[i].n) }
    }
}
function cableNegUndoWithRivalRelief(ups, downs) {
    var i, grossUp = 0
    ups = ups || []
    for (i = 0; i < ups.length; i++) { grossUp += ups[i].n }
    downs = cableNegEffectiveRelief(downs, grossUp)
    for (i = 0; i < ups.length; i++) { cableNegReprisalSub(ups[i].corp, ups[i].n) }
    for (i = 0; i < downs.length; i++) {
        if (downs[i].n > 0) { cableNegReprisalAdd(downs[i].corp, downs[i].n) }
    }
}
