    Q.cableNegReprisalSub('magrail', Q.CABLE_NEG_REPR_EDU_ENROLL_EACH)
    Q.cableNegReprisalSub('brazos', Q.CABLE_NEG_REPR_EDU_ENROLL_EACH)
    Q.cable_neg_education_enroll = 0
}
Q.cableNegSyncCorpStances = function() {
    function stanceFor(corp) {
        var margin = (Number(Q[corp + '_leverage']) || 0) - (Number(Q[corp + '_reprisal']) || 0)
        var cat = 1
