var CONTRACTING_VISITS_PER_PHASE = 2

var CONTRACT_PATRONAGE_FLAGS = [
    'contract_big3_docks',
    'contract_big3_vats',
    'contract_big3_railyard',
    'contract_big3_limelight',
    'contract_wealthy_docks',
    'contract_wealthy_aurora',
    'contract_coop_aurora',
    'contract_coop_pitts',
    'contract_coop_deeps',
    'contract_coop_docks'
]
var FAIR_LEAD_OVER_PATRONAGE = 3

/** Forced honest bidding when fair contracts lead patronage (excl. outside corps) by this many. */
function syncContractFairChainComplete() {
    var patronageCount = 0
    for (var i = 0; i < CONTRACT_PATRONAGE_FLAGS.length; i++) {
        if ((Number(Q[CONTRACT_PATRONAGE_FLAGS[i]]) || 0) >= 1) {
            patronageCount += 1
        }
    }
    Q.contract_patronage_count = patronageCount
    var fairCount = Number(Q.fair_contract_uses) || 0
    var outsideCount = Number(Q.contract_outside) || 0
    var totalAwards = outsideCount + fairCount + patronageCount
    Q.contract_award_total = totalAwards
    Q.contract_outside_below_quarter = (totalAwards < 1 || outsideCount * 4 < totalAwards) ? 1 : 0
    Q.contract_fair_chain_complete = (fairCount >= patronageCount + FAIR_LEAD_OVER_PATRONAGE) ? 1 : 0
    return Q.contract_fair_chain_complete
}

/** Grant 2 contracting draws per phase; unused visits bank for later phases. */
function syncContractingAllowance() {
    var phase = Number(Q.phase)
    if (isNaN(phase) || phase < 1) { phase = 1 }
    var through = Number(Q.contracting_allowance_through_phase)
    if (isNaN(through) || through < 0) { through = 0 }
    if (phase > through) {
        var grant = (phase - through) * CONTRACTING_VISITS_PER_PHASE
        Q.contracting_visits_remaining = (Number(Q.contracting_visits_remaining) || 0) + grant
        Q.contracting_allowance_through_phase = phase
    }
    if (Q.contracting_visits_remaining == null || isNaN(Number(Q.contracting_visits_remaining))) {
        Q.contracting_visits_remaining = 0
    }
    return Number(Q.contracting_visits_remaining) || 0
}

var ACTION_RESERVE_MAX = 4

/** Recompute Q.month_actions_remaining from reserve, limit, and used this month. */
function syncActionEconomyDisplay() {
    var limit = Number(Q.month_actions_limit)
    if (isNaN(limit) || limit < 1) { limit = 2 }
    var used = Number(Q.month_actions_used) || 0
    var reserve = Number(Q.action_reserve) || 0
    if (reserve < 0) { reserve = 0 }
    if (reserve > ACTION_RESERVE_MAX) { reserve = ACTION_RESERVE_MAX }
    Q.action_reserve = reserve
    Q.month_actions_used = used
    Q.month_actions_limit = limit
    var slotsLeft = Math.max(0, limit - used)
    Q.month_actions_remaining = Math.min(slotsLeft, reserve)
    return Q.month_actions_remaining
}

Q.canSpendOrganizingAction = function() {
    syncActionEconomyDisplay()
    return (Number(Q.month_actions_remaining) || 0) > 0
}

Q.spendOrganizingAction = function() {
    if (!Q.canSpendOrganizingAction()) { return false }
    Q.action_reserve = (Number(Q.action_reserve) || 0) - 1
    Q.month_actions_used = (Number(Q.month_actions_used) || 0) + 1
    syncActionEconomyDisplay()
    return true
}

/** Month-start: +1 reserve (cap 4), reset used, set limit 2 or 3 if idle last month. */
Q.beginActionEconomyMonth = function() {
    var usedLast = Number(Q.month_actions_used) || 0
    Q.actions_used_last_month = usedLast
    Q.month_actions_used = 0
    Q.month_actions_limit = (usedLast === 0) ? 3 : 2
    var reserve = Number(Q.action_reserve) || 0
    Q.action_reserve = Math.min(ACTION_RESERVE_MAX, reserve + 1)
    syncActionEconomyDisplay()
}

function monthly_tick_phase1() {
    if (typeof Q.beginActionEconomyMonth === 'function') {
        Q.beginActionEconomyMonth()
    }
    syncContractingAllowance()
    organize_tick()
    if (typeof Q.cableNegPromiseMonthlyTick === 'function') {
        Q.cableNegPromiseMonthlyTick()
    }
    trade_level_tick()
    economy_tick()
    applyStratumProsperityBumps()
    if (typeof Q.applyEconomicAssetProsperity === 'function') {
        Q.applyEconomicAssetProsperity()
    }
    applyProsperityConnections()
    if (typeof Q.processMonthlyHousing === 'function') {
        Q.processMonthlyHousing()
    }
    if (typeof Q.tabulateBudget === 'function') {
        Q.tabulateBudget()
    }
    syncProsperityDisplays()
    if (typeof Q.syncIgAttitudes === 'function') { Q.syncIgAttitudes() }
}

/** Add amount to every voter block in one district; sync prosperity displays. */
function bumpDistrictProsperity(districtId, amount) {
    var state = Q.electionV2
    if (!state || !state.blocks) { return false }
    var bump = Number(amount)
    if (isNaN(bump) || bump === 0) { return false }
    for (var i = 0; i < state.blocks.length; i++) {
        var block = state.blocks[i]
        if (block.district.id !== districtId) { continue }
        block.prosperity = clampProsperity(
            (block.prosperity ?? PROSPERITY_BLOCK_BASELINE) + bump
        )
    }
    if (typeof Q.qified_block_prosperity === 'function') {
        Q.qified_block_prosperity()
    }
    if (typeof Q.syncStratumProsperityAverages === 'function') {
        Q.syncStratumProsperityAverages()
    }
    return true
}

