tool_input.command:
cd /home/airy/mikasa && node -e "
var ACTION_RESERVE_MAX = 4, ACTION_SURGE_BONUS = 2, ACTION_SURGE_UNLIMITED = 999;
function applySurge(Q) {
  var phase = Number(Q.phase) || 1, granted = Number(Q.action_surge_granted_through_phase) || 0;
  if (phase <= granted) return false;
  Q.action_surge_granted_through_phase = phase;
  Q.action_surge_active = 1;
  Q.action_reserve = (Number(Q.action_reserve)||0) + ACTION_SURGE_BONUS;
  Q.month_actions_limit = ACTION_SURGE_UNLIMITED;
  return true;
}
function sync(Q) {
  var surge = Q.action_surge_active === 1;
  var limit = Q.month_actions_limit || 2, used = Q.month_actions_used||0, reserve = Q.action_reserve||0;
  if (!surge && reserve > ACTION_RESERVE_MAX) reserve = ACTION_RESERVE_MAX;
  Q.action_reserve = reserve;
  Q.month_actions_remaining = surge ? reserve : Math.min(Math.max(0, limit-used), reserve);
  return Q;
}
function begin(Q) {
  var usedLast = Q.month_actions_used||0;
  Q.action_surge_active = 0;
  Q.month_actions_used = 0;
  Q.month_actions_limit = usedLast === 0 ? 3 : 2;
  var reserve = Q.action_reserve||0;
  if (reserve > ACTION_RESERVE_MAX) reserve = ACTION_RESERVE_MAX;
  Q.action_reserve = Math.min(ACTION_RESERVE_MAX, reserve + 1);
  applySurge(Q);
  return sync(Q);
}
function spend(Q) {
  sync(Q);
  if (Q.month_actions_remaining <= 0) return false;
  Q.action_reserve--; Q.month_actions_used++;
  return sync(Q), true;
}
// Jan phase 1 start
var Q = { phase: 1, action_surge_granted_through_phase: 0, action_reserve: 0 };
begin(Q);
console.log('Jan P1 surge:', Q.action_reserve, 'rem', Q.month_actions_remaining, 'surge', Q.action_surge_active);
while (spend(Q)) {}
console.log('Jan spent all:', Q.action_reserve, 'used', Q.month_actions_used);
// Feb normal
begin(Q);
console.log('Feb normal:', Q.action_reserve, 'limit', Q.month_actions_limit, 'rem', Q.month_actions_remaining, 'surge', Q.action_surge_active);
// Mid-June phase 2
Q.phase = 2; Q.action_reserve = 3;
applySurge(Q); sync(Q);
console.log('Jun P2 surge mid-month:', Q.action_reserve, 'rem', Q.month_actions_remaining);
spend(Q); spend(Q); spend(Q); spend(Q); spend(Q);
console.log('Jun after 5 spends:', Q.action_reserve, 'used', Q.month_actions_used);
begin(Q);
console.log('Jul after surge:', Q.action_reserve, 'limit', Q.month_actions_limit, 'surge', Q.action_surge_active);
"

